<?php

namespace Modules\Repile\Support;

class AutoHeaders
{
    public const NAMES = [
        'auto-submitted',
        'x-autoreply',
        'x-autorespond',
        'x-autoresponder',
        'x-autogenerated',
        'precedence',
        'x-precedence',
    ];

    private const MAX_VALUE = 200;

    public static function from($raw)
    {
        $raw = (string) $raw;
        if ($raw === '') {
            return [];
        }
        $unfolded = preg_replace('/\r?\n[ \t]+/', ' ', $raw);
        $found = [];
        foreach (preg_split('/\r?\n/', $unfolded) as $line) {
            $parts = explode(':', $line, 2);
            if (count($parts) !== 2) {
                continue;
            }
            $name = trim($parts[0]);
            if (!in_array(strtolower($name), self::NAMES, true)) {
                continue;
            }
            $found[] = [
                'name' => $name,
                'value' => mb_substr(trim($parts[1]), 0, self::MAX_VALUE),
            ];
        }

        return $found;
    }
}
